  if (scenarioValue) {
    if (FIX_SCENARIOS.has(scenarioValue)) {
      return 'fix_ci';
    }
    if (VERIFY_SCENARIOS.has(scenarioValue)) {
      return 'verify';
    }
    if (FEATURE_SCENARIOS.has(scenarioValue)) {
      return 'normal';
    }
  }

